def brute(people):
    tot=sum(v for _,v in people)
    if tot%3!=0:
        return None, tot
    target=tot//3
    n=len(people)
    best=float('inf')
    best_assign=None
    for assign in product([1,2,3], repeat=n):
        sums=[0,0,0]
        for (orig,stren),dst in zip(people,assign):
            sums[dst-1]+=stren
        if sums[0]==target and sums[1]==target and sums[2]==target:
            moves=sum(1 for (orig,_),dst in zip(people,assign) if orig!=dst)
            if moves<best:
                best=moves
                best_assign=assign
                if best==0:
                    break
    return best,best_assign

def test_a():
    people=[(1, 2), (2, 5), (1, 5), (3, 3), (1, 3), (3, 6)]
    best,assign=brute(people)
    assert False, f"best {best} assign {assign}"

