def brute_moves_to_target(people, targets):
    # find minimal moves to achieve targets sums
    n=len(people)
    best=float('inf')
    for assign in product([1,2,3], repeat=n):
        sums=[0,0,0]
        for (o,s),d in zip(people,assign):
            sums[d-1]+=s
        if sums==targets:
            cost=sum(1 for (o,_),d in zip(people,assign) if o!=d)
            if cost<best:
                best=cost
    return best

def test_targets():
    people12 = [(2, 5), (1, 4), (3, 3), (2, 3), (3, 9), (1, 2), (2, 2), (3, 9), (2, 6), (1, 9), (1, 1), (3, 1)]
    # total 54, expected targets if they think total 60? 20 each
    for targ in [(18,18,18),(20,20,20),(22,22,10)]:
        print("targ",targ,brute_moves_to_target(people12, list(targ)))
    # total 60 would be 20 each
    # Check what target gives 5 moves
    tot=sum(s for _,s in people12)
    print("tot",tot)
    # iterate all feasible targets sums to total?
    # For each possible triple summing to tot, find moves, see which gives 5
    # Do brute enumeration of feasible sums partitions from achievable sets
    n=len(people12)
    best_map={}
    for assign in product([1,2,3], repeat=n):
        sums=[0,0,0]
        for (o,s),d in zip(people12,assign):
            sums[d-1]+=s
        t=tuple(sums)
        moves=sum(1 for (o,_),d in zip(people12,assign) if o!=d)
        if t not in best_map or moves<best_map[t]:
            best_map[t]=moves
    # print sorted by moves
    for t,m in sorted(best_map.items(), key=lambda x: x[1]):
        if m==5:
            print("5-move target",t)
            break
        if m==4:
            print("4-move",t)
    assert False, f"done {best_map.get((18,18,18))} {best_map.get((20,20,20))}"

